<div class="fm-search" x-data="{ query: '', matches: [], search() { this.matches = [...document.querySelectorAll('.sidebar-link')].filter(link => this.query.trim() && link.textContent.toLowerCase().includes(this.query.toLowerCase())).slice(0, 7).map(link => ({title:link.textContent.trim(), url:link.href})); } }" @click.outside="query = ''; matches = []">
<i class="fas fa-magnifying-glass"></i><input aria-label="Search modules" placeholder="Search your workspace…" x-model="query" @input="search()" @keydown.escape="query = ''; matches = []"><div class="fm-search-results" x-show="query.trim()" x-cloak><template x-for="match in matches" :key="match.url"><a :href="match.url" x-text="match.title"></a></template><p x-show="matches.length === 0" class="text-xs p-3" style="color:var(--text-muted)">No matching modules</p></div>
</div>
